static class MultiMethodServlet extends HttpServlet {

    protected void doPut(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String body = new String(req.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
        resp.getWriter().write("PUT: zasob zastapiony danymi: " + body);
    }

    protected void doDelete(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        resp.getWriter().write("DELETE: usunieto zasob");
    }

    protected void service(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        if ("PATCH".equals(req.getMethod())) {
            String body = new String(req.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
            resp.getWriter().write("PATCH: czesciowa aktualizacja: " + body);
            return;
        }
        super.service(req, resp); // dla GET/POST/PUT/DELETE - standardowe dzialanie
    }
}

// HttpRequest.Builder NIE MA metody .PATCH() (podobnie jak
// HttpServlet nie ma doPatch()) - to nie przeoczenie, tylko konsekwencja
// tego, ze PATCH nigdy nie trafil do "oficjalnej" listy metod tych API.
// Zeby wyslac PATCH, uzywamy ogolnej metody .method(nazwa, body):

HttpRequest patchRequest = HttpRequest.newBuilder(URI.create(url + "?id=7"))
        .method("PATCH", HttpRequest.BodyPublishers.ofString("{\"cena\":3900}"))
        .build();

// Podobnie DELETE ma gotowy skrot .DELETE():
HttpRequest deleteRequest = HttpRequest.newBuilder(URI.create(url + "?id=7"))
        .DELETE()
        .build();
